python
def ribbonTotalsThresholdFile(readings, k):
    a=readings
    out=[]
    total=0
    for x in a:
        total+=x
        out.append(total)
    return sum(x>=k for x in out)


java
class Solution {
  public int ribbonTotalsThresholdFile(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int total=0;for(int x:a){total+=x;out.add(total);}}
    int answer=0;for(int x:out)if(x>=k)answer++;return answer;
  }
}
